      "description": "系统运维概览仪表板",
      "widgets": [
        {
          "type": "STREAM_SEARCH_RESULT_COUNT",
          "config": {
            "timerange": {
              "type": "relative",
              "range": 3600
            },
            "query": "level:ERROR OR level:FATAL",
            "stream_id": "system-errors"
          },
          "col": 1,
          "row": 1,
          "height": 2,
          "width": 2
        },
        {
          "type": "QUICKVALUES",
          "config": {
            "timerange": {
              "type": "relative", 
              "range": 86400
            },
